function CatHousePrivilegeCard:FreshUI()
    local privilegeRewardsVo = self.privilegeRewardsVo
    self.Text.text           = localize("立即获得猫眼石")
    self.TxtDetails.text     = localize("孵化时间减少半小时增加一个坑位")

    -----------------------------------
    --- 刷新购买后获取道具
    local firstGoods         = privilegeRewardsVo.firstGoods
    if next(firstGoods) then
        local firstGoods = firstGoods[1]
        local goodsId   = firstGoods.goodsId
        ---@type GoodsVo
        local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(goodsId)
        self.ImgIcon:LoadSprite(goodsVo.photoPath)

        local goodsNum   = firstGoods.goodsNum
        self.TxtNum.text = string.format("x%s", goodsNum)

    end

    -----------------------------------
    --- 刷新每日道具
    local everyDayGoods  = privilegeRewardsVo.everyDayGoods
    if next(everyDayGoods) then
        ---@type GoodNodeMB
        local luaEnv = CfUtils.GetLuaScr(self.GoodNode, GoodsNodeMBPath)
        if luaEnv then
            local everyDayGood = everyDayGoods[1]
            luaEnv:Reload({
                goodsId  = everyDayGood.goodsId,
                text     = "x" .. tostring(everyDayGood.goodsNum),
                isShowNo = true
            })
            luaEnv:SetClickCallback(function(goodsId)
                local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(everyDayGood.goodsId)
                if isTable(vo) then
                    GameUtils.ShowCommonTipsBoard(self.GoodNode.gameObject, vo.name, vo.desc, vo.quality, vo.id)
                end
            end)
        end
    end

    -----------------------------------
    --- 刷新特权卡消耗数量

    --- 购买特权卡消耗数量
    local privilegeCard = self.catHouseComp:GetPrivilegeCardById(self.privilegeCardId)
    local price         = privilegeCard.price   
    local windowsPriceId = CfUtils.GetWindowsPriceId(privilegeCard)
    self.TxtNumber.text = localize('_YUAN__num_',{_num_=CfUtils.GetPrice(windowsPriceId , privilegeCard.channelProductId)   , _YUAN_ = CfUtils.GetCurrerySymbol()})
    -----------------------------------
    --- 刷新特权卡倒计时
    if self:FreshCountdown() then
        self:FreshTxtGetNumber(privilegeCard)
        self:FreshTxtBuy(true)
        self:RegTimeChangeEvent()
    end
end


---FreshCountdown
---刷新特权卡倒计时
function CatHousePrivilegeCard:FreshCountdown()
    local seconds          = self.catHouseComp:GetPrivilegeCardSecondsById(self.privilegeCardId) 
    local isShowSeconds   = seconds > 0
    KTool.SetActive(self.TxtTime.gameObject, isShowSeconds)
    if isShowSeconds then
        --- 最后7天红色
        self.TxtTime.text = seconds <= 7*86400 and 
            localize("(剩余:<color=#ff4d4d>_day_</color>)", {_day_ = GetTimeHMS(seconds)}) 
            or 
            localize("(剩余:_day_)", {_day_ = GetTimeHMS(seconds)}) 
    else
        KTool.SetActive(self.TxtGetNumber.gameObject, false)
        self:FreshTxtBuy(false)    
    end
    return isShowSeconds
end

function CatHousePrivilegeCard:FreshTxtBuy(isBuy)
    CfUtils.FillText(self.Txtbuy, isBuy and localize("续费") or localize("购买"))
end

function CatHousePrivilegeCard:RegTimeChangeEvent()
    if self.__EventCatHouseTimeChange then return end
    self.__EventCatHouseTimeChange = Events.AddListener(CatHouseTimeChange, Bind(self, self.OnEventCatHouseTimeChange))
end

function CatHousePrivilegeCard:UnRegTimeChangeEvent()
    if self.__EventCatHouseTimeChange then
        Events.RemoveListener(CatHouseTimeChange, self.__EventCatHouseTimeChange)
        self.__EventCatHouseTimeChange = nil
    end
end

function CatHousePrivilegeCard:FreshTxtGetNumber(privilegeCard)
    local remainSeconds = self.catHouseComp:GetPrivilegeCardSecondsById(self.privilegeCardId)
    KTool.SetActive(self.TxtGetNumber.gameObject, remainSeconds > 0)
    if remainSeconds > 0 then
        self.TxtGetNumber.text = localize("(剩余:_num_)", {_num_ = privilegeCard.leftDrawnNum})
    end
end

