function CatHousePrivilegeCard:OnEventSdkEvent(parameters)
    --- sdk pay succeed
    if parameters.event == Constants.EventNames.EVENT_SDK_PAY then
        local data = parameters.data
        if isNull(data) then
           return
        end
        --- 当前如果是商店月卡 ， 直接返回
        if isSet(data, "monthCard") then
           return
        end
        local privilegeRewardsVo = self.privilegeRewardsVo
        ---@type PlayerComponent
        local component       = self.catHouseComp
        ---1. 更新特权卡持续时间
        local oldSeconds     = component:GetPrivilegeCardSecondsById(self.privilegeCardId)
        local cycle          = privilegeRewardsVo.cycle
        local expirationTime = cycle * 3600 * 24 + oldSeconds
        local privilegeCard  = component:GetPrivilegeCardById(self.privilegeCardId)
        --- 以前有加30 没有加29
        local leftDrawnNum = privilegeCard.leftDrawnNum
        privilegeCard.leftDrawnNum = leftDrawnNum + (oldSeconds > 0 and cycle or (cycle - 1))
        privilegeCard.remainSeconds = expirationTime
        
        local seatNum = privilegeRewardsVo.seatNum
        ---@type CatHouseComponent
        ---@type ECSWorldMgr
        local worldMgr = ECSWorldMgr:GetInstance()
        ---@type ECSWorld
        local world = worldMgr:GetWorld(Constants.GameWorld)
        if world:HasEntity(Constants.CatHouseEntityId) then
            local  catHouseComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CatHouseComponent, Constants.CatHouseEntityId)
            if not isNull(catHouseComponent) then
                catHouseComponent:AddDeliveryData(seatNum, expirationTime)
            end
        end
        ---3. 更新当前界面倒计时
        self:RegTimeChangeEvent()
        self:FreshTxtBuy(true)
        self:FreshTxtGetNumber(privilegeCard)
        self:FreshCountdown()
    end
end

